[Collection(FakeNknNetworkCollection.Name)]
[Trait("Area", "Core")]
public sealed class NknAccelerationTransportTests : CoreSmokeTestsBase, IDisposable
{
    public NknAccelerationTransportTests()
    {
        ResetAccelerationOverridesForTests();
        FakeNknClient.ResetNetwork();
    }

    public void Dispose()
    {
        ResetAccelerationOverridesForTests();
        FakeNknClient.ResetNetwork();
    }

    [Theory]
    [Trait("Category", "Smoke")]
    [InlineData((int)MsgType.TransportAccelerationPayerIntent)]
    [InlineData((int)MsgType.TransportAccelerationOffer)]
    [InlineData((int)MsgType.TransportAccelerationAnswer)]
    [InlineData((int)MsgType.TransportAccelerationAnswerAck)]
    [InlineData((int)MsgType.TransportAccelerationDown)]
    public void TransportAccelerationAckTimeout_IsTransactionScopedNotSessionFatal(int messageTypeValue)
    {
        var messageType = (MsgType)messageTypeValue;
        var method = typeof(NknSignalingTransport).GetMethod(
            "ShouldDisconnectOnAckTimeout",
            BindingFlags.Static | BindingFlags.NonPublic);

        Assert.NotNull(method);
        var shouldDisconnect = Assert.IsType<bool>(method!.Invoke(null, new object[] { messageType }));

        Assert.False(shouldDisconnect);
    }

    [Fact]
    [Trait("Category", "Smoke")]
    public void SessionHandshakeAckTimeout_RemainsSessionFatal()
    {
        var method = typeof(NknSignalingTransport).GetMethod(
            "ShouldDisconnectOnAckTimeout",
            BindingFlags.Static | BindingFlags.NonPublic);

        Assert.NotNull(method);
        var shouldDisconnect = Assert.IsType<bool>(method!.Invoke(null, new object[] { MsgType.SessionHandshakeStart }));

        Assert.True(shouldDisconnect);
    }

    [Fact]
    [Trait("Category", "Smoke")]
    public void RuntimeUnlockPendingNegotiation_PreservesConcreteRetryReason()
    {
        FakeNknClient.ResetNetwork();
        try
        {
            var options = NknTransportOptions.Load();
            var hostClient = new FakeNknClient("host.runtime-unlock-pending-reason.address");
            using var host = new NknSignalingTransport(
                hostClient,
                options,
                new NknIdentity("host-runtime-unlock-pending-reason-id", hostClient.Address),
                NknTunaAccelerationOptions.Disabled,
                new RetryableTunaAccelerationSession(canListen: true, failedDialAttemptsBeforeSuccess: 0));

            InvokePrivateMethod(
                host,
                "MarkPendingRuntimeUnlockAccelerationNegotiation",
                "runtime_unlock_after_fallback_tail_quiescent");

            Assert.Equal(1, Assert.IsType<int>(GetPrivateField(host, "pendingRuntimeUnlockAccelerationNegotiation")));
            Assert.Equal(
                "runtime_unlock_after_fallback_tail_quiescent",
                Assert.IsType<string>(GetPrivateField(host, "pendingRuntimeUnlockAccelerationNegotiationReason")));
            Assert.Equal(
                "InitialActivation",
                GetPrivateField(host, "pendingRuntimeUnlockAccelerationNegotiationAuthorityMode")?.ToString());
            Assert.Null(GetPrivateField(host, "pendingRuntimeUnlockAccelerationNegotiationInstallReceipt"));

            InvokePrivateMethod(host, "ClearPendingRuntimeUnlockAccelerationNegotiation");

            Assert.Equal(0, Assert.IsType<int>(GetPrivateField(host, "pendingRuntimeUnlockAccelerationNegotiation")));
            Assert.Null(GetPrivateField(host, "pendingRuntimeUnlockAccelerationNegotiationReason"));
        }
        finally
        {
            FakeNknClient.ResetNetwork();
        }
    }

    [Fact]
    [Trait("Category", "Smoke")]
    public void RuntimeUnlockPendingNegotiation_QueuesBehindPendingOfferAndWakesWhenCleared()
    {
        FakeNknClient.ResetNetwork();
        try
        {
            var options = NknTransportOptions.Load();
            var hostClient = new FakeNknClient("host.runtime-unlock-pending-offer-wake.address");
            using var host = new NknSignalingTransport(
                hostClient,
                options,
                new NknIdentity("host-runtime-unlock-pending-offer-wake-id", hostClient.Address),
                NknTunaAccelerationOptions.Disabled,
                new RetryableTunaAccelerationSession(canListen: true, failedDialAttemptsBeforeSuccess: 0));

            const string nonce = "aa11223344556677889900aabbccddee";
            SetPrivateField(host, "outboundAccelerationOfferNonce", nonce);
            SetPrivateField(host, "outboundAccelerationOfferPayerDecisionId", 42L);
            SetPrivateField(host, "outboundAccelerationOfferGeneration", 7L);
            var logStart = GetOperationalLogLength();

            var queued = Assert.IsType<bool>(InvokePrivateMethod(
                host,
                "TryQueueRuntimeUnlockNegotiationBehindPendingGeneration",
                "runtime_unlock_after_fallback_tail_quiescent",
                "unit_test_pending_offer"));

            Assert.True(queued);
            Assert.Equal(1, Assert.IsType<int>(GetPrivateField(host, "pendingRuntimeUnlockAccelerationNegotiation")));
            Assert.Equal(
                "runtime_unlock_after_fallback_tail_quiescent",
                Assert.IsType<string>(GetPrivateField(host, "pendingRuntimeUnlockAccelerationNegotiationReason")));
            Assert.Equal(
                "InitialActivation",
                GetPrivateField(host, "pendingRuntimeUnlockAccelerationNegotiationAuthorityMode")?.ToString());
            Assert.Null(GetPrivateField(host, "pendingRuntimeUnlockAccelerationNegotiationInstallReceipt"));

            InvokePrivateMethod(host, "ClearOutboundAccelerationOfferIfCurrent", nonce, 42L, 7L, "unit_test_offer_cleared");

            Assert.Equal(0, Assert.IsType<int>(GetPrivateField(host, "pendingRuntimeUnlockAccelerationNegotiation")));
            Assert.Null(GetPrivateField(host, "pendingRuntimeUnlockAccelerationNegotiationReason"));
            var logTail = ReadOperationalLogTail(logStart);
            Assert.Contains("event=tuna_acceleration_runtime_unlock_queued_behind_pending_generation;", logTail, StringComparison.Ordinal);
            Assert.Contains("wait_reason=unit_test_pending_offer", logTail, StringComparison.Ordinal);
            Assert.Contains("event=tuna_acceleration_runtime_unlock_pending_negotiation_wake_scheduled;", logTail, StringComparison.Ordinal);
            Assert.Contains("trigger=outbound_offer_cleared", logTail, StringComparison.Ordinal);
        }
        finally
        {
            FakeNknClient.ResetNetwork();
        }
    }

