                sessionId,
                "runtime_unlock")));

            InvokePrivateMethod(
                host,
                "ArmRuntimeUnlockRetryAfterRecovery",
                708L,
                sessionId,
                "runtime_unlock_offer_send_not_observed",
                "runtime_unlock_offer_send_not_observed",
