    [Fact]
    [Trait("Category", "Smoke")]
    public void RuntimeUnlockRetryAfterRegularV4Settlement_HeldDispatchBranchesResumePrePayerPause()
    {
        var repoRoot = FindRepoRoot();
        var sourcePath = Path.Combine(repoRoot, "src", "nLink.Infra.Nkn", "NknSignalingTransport.Acceleration.cs");
        var source = File.ReadAllText(sourcePath).Replace("\r\n", "\n", StringComparison.Ordinal);

        void AssertResumeBeforeBranchReturn(string branchMarker, string reason)
        {
            var branchIndex = source.IndexOf(branchMarker, StringComparison.Ordinal);
            Assert.True(branchIndex >= 0, $"Missing branch marker '{branchMarker}'.");
            var resumeIndex = source.IndexOf("ResumeActivationPauseIfNeeded(", branchIndex, StringComparison.Ordinal);
            Assert.True(resumeIndex >= 0, $"Missing activation-pause resume after '{branchMarker}'.");
            var reasonIndex = source.IndexOf(reason, resumeIndex, StringComparison.Ordinal);
            Assert.True(reasonIndex >= 0, $"Missing activation-pause resume reason '{reason}'.");
            var returnIndex = source.IndexOf("return;", reasonIndex, StringComparison.Ordinal);
            Assert.True(returnIndex >= 0, $"Missing branch return after resume reason '{reason}'.");
            Assert.InRange(returnIndex - branchIndex, 1, 1200);
        }

        Assert.Contains("ShouldPauseRegularNknV4FileTransferBeforeRuntimeUnlockPayerIntent", source, StringComparison.Ordinal);
        Assert.Contains("runtime_unlock_retry_dispatch_payer_intent", source, StringComparison.Ordinal);
        Assert.DoesNotContain(
            "TryDeferRuntimeUnlockOfferDispatchForRegularV4ReceiveRecovery",
            source,
            StringComparison.Ordinal);
        AssertResumeBeforeBranchReturn(
            "TryDeferRuntimeUnlockOfferDispatchForRegularV4FrontierRepair",
            "regular_v4_frontier_repair_pending");
        AssertResumeBeforeBranchReturn(
            "dispatchAuthorityResult == RuntimeUnlockRetryDispatchAuthorityResult.Held",
            "runtime_unlock_retry_dispatch_authority_held");
    }

    [Fact]
    [Trait("Category", "Smoke")]
    [Trait("FileTransferInfraSuite", "FallbackTailCoordinatorAggregate")]
    public void FallbackTailCoordinatorAggregate_InfraHasNoFallbackAuthorityOrReasonDerivedEligibility()
    {
        var repoRoot = FindRepoRoot();
        var acceleration = File.ReadAllText(
            Path.Combine(
                repoRoot,
                "src",
                "nLink.Infra.Nkn",
                "NknSignalingTransport.Acceleration.cs"));
        var adapter = File.ReadAllText(
            Path.Combine(
                repoRoot,
                "src",
                "nLink.Infra.Nkn",
                "RealNknClientAdapter.cs"));
        var source = acceleration + Environment.NewLine + adapter;

        foreach (var forbidden in new[]
                 {
                     "postTunaFallbackLegAuthority",
                     "RuntimeUnlockRetryFallbackTailUnblockRecheckIntent",
                     "TryMarkRuntimeUnlockPostTunaFallbackFinalAuthorityProbeCandidate",
                     "ShouldSoftSettleRuntimeUnlockRetryAfterFallbackRepair",
                     "ShouldAllowAccelerationRetryDespiteFallbackControlProofPending",
                     "ShouldAllowRuntimeUnlockRetryForActivePostTunaFallbackRepair",
                     "ShouldTrustRuntimeUnlockObservedSendWithPostTunaFallbackRepairProof",
                     "TryGetCurrentPostTunaFallbackObservedSendProbeProof",
                     "ScheduleRuntimeUnlockRetryAfterFallbackRepairSoftSettle",
                     "ShouldAllowPostTunaFallbackControlPlanePressureAfterProof",
                     "HasFreshPostTunaFallbackReceiverFrontierProofHint",
                     "ShouldProtectPostTunaFallbackAvailabilityDuringRuntimeUnlockRecovery",
                     "IsRuntimeUnlockPostTunaFallbackOfferRecoveryReason",
                     "FileTransferPostTunaFallbackRepairProofHint",
                     "fileTransferPostTunaFallbackRepairProofHints",
                     "FileTransferPostTunaFallbackRepairProofFreshness",
                     "fileTransferPostTunaFallbackYieldRuntimeUnlockRetries",
                 })
        {
            Assert.DoesNotContain(forbidden, source, StringComparison.Ordinal);
        }

        Assert.Contains(
            "TryGetEffectiveFallbackPairedTailYieldInstallReceiptForSession",
            acceleration,
            StringComparison.Ordinal);
        Assert.Contains(
            "reason=fallback_paired_tail_yield_install_receipt",
            acceleration,
            StringComparison.Ordinal);
        Assert.Contains(
            "event=filetransfer_post_tuna_fallback_control_plane_pressure_observed;",
            adapter,
            StringComparison.Ordinal);
        Assert.Contains(
            "authority_effect=none; decision_reason=coordinator_fallback_tail_evaluation_required",
            adapter,
            StringComparison.Ordinal);
    }

    [Fact]
    [Trait("Category", "Smoke")]
    public async Task RuntimeUnlockRetryAfterRecovery_PayerIntentRejectionRequestsSuccessorBeforeDispatchObserved()
    {
        FakeNknClient.ResetNetwork();
        var previousHelpeePriorityDelay = NknSignalingTransport.HelperPaidOfferHelpeePriorityDelayOverrideForTests;
        var previousSoftSettleDelay = NknSignalingTransport.RuntimeUnlockRecoverySoftSettleDelayOverrideForTests;
        NknSignalingTransport.HelperPaidOfferHelpeePriorityDelayOverrideForTests = TimeSpan.Zero;
        NknSignalingTransport.RuntimeUnlockRecoverySoftSettleDelayOverrideForTests = TimeSpan.Zero;
        try
        {
            using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(8));
            var options = NknTransportOptions.Load();
            var hostClient = new FakeNknClient("host.runtime-unlock-payer-intent-rejected.address");
            var helperClient = new FakeNknClient("helper.runtime-unlock-payer-intent-rejected.address");
            using var host = new NknSignalingTransport(
                hostClient,
                options,
                new NknIdentity("host-runtime-unlock-payer-intent-rejected-id", hostClient.Address),
                NknTunaAccelerationOptions.Disabled,
                new RetryableTunaAccelerationSession(canListen: true, failedDialAttemptsBeforeSuccess: 0));
            using var helper = new NknSignalingTransport(
                helperClient,
                options,
                new NknIdentity("helper-runtime-unlock-payer-intent-rejected-id", helperClient.Address));

            var sessionId = await ApproveNknSessionAsync(
                host,
                helper,
                cts.Token,
                InviteCapabilities.Chat | InviteCapabilities.FileTransfer | InviteCapabilities.ScreenShare);
            const string transferId = "transfer_runtime_unlock_payer_intent_rejected";
            InstallRuntimeUnlockRetryDispatchCoordinatorForTests(host);
            _ = await host.OpenFileTransferDataSessionAsync(sessionId, transferId, cts.Token);
            TrackAuthorizedRegularV4RouteForTests(host, transferId);

            var logStart = GetOperationalLogLength();
            InvokePrivateMethod(
                host,
                "ArmRuntimeUnlockRetryAfterRecovery",
                709L,
                sessionId,
                "runtime_unlock_offer_send_not_observed",
                "runtime_unlock_offer_send_not_observed",
                false);
            InvokePrivateMethod(host, "ScheduleRuntimeUnlockRetryAfterRecoveryIfArmed", "test_recovery_settled");
            InvokePrivateMethod(host, "MarkRuntimeUnlockRecoveryContractRetryDispatched", "runtime_unlock");
            Assert.True(
                BindRuntimeUnlockRetryDispatchOfferAliasAndObserveForTests(
                    host,
                    offerGeneration: 710L,
                    offerNonce: "payer-intent-rejected-before-dispatch"));
            var retryStateField = typeof(NknSignalingTransport).GetField(
                "runtimeUnlockRecoveryRetryState",
                BindingFlags.Instance | BindingFlags.NonPublic);
            var retryState = retryStateField!.GetValue(host);
            var dispatchContract = Assert.IsType<RuntimeUnlockRetryDispatchContract>(
                retryState!.GetType().GetProperty("DispatchContract")!.GetValue(retryState));

            var uncapturedCallback = Assert.IsType<bool>(InvokePrivateMethod(
                host,
                "TrySettleRuntimeUnlockRetryDispatchMissingBeforeOfferIfCurrent",
                sessionId,
                "runtime_unlock_payer_intent_send_rejected_before_retry_dispatch",
                "runtime_unlock_payer_intent_send_rejected",
                false,
                null));
            Assert.True(uncapturedCallback);
            Assert.False(dispatchContract.Lifecycle.IsSettled);

            var settled = Assert.IsType<bool>(InvokePrivateMethod(
                host,
                "TrySettleRuntimeUnlockRetryDispatchMissingBeforeOfferIfCurrent",
                sessionId,
                "runtime_unlock_payer_intent_send_rejected_before_retry_dispatch",
                "runtime_unlock_payer_intent_send_rejected",
                false,
                dispatchContract.Authority.AuthorityId));

            Assert.True(settled);
            var duplicate = Assert.IsType<bool>(InvokePrivateMethod(
                host,
                "TrySettleRuntimeUnlockRetryDispatchMissingBeforeOfferIfCurrent",
                sessionId,
                "runtime_unlock_payer_intent_send_rejected_before_retry_dispatch",
                "runtime_unlock_payer_intent_send_rejected",
                false,
                dispatchContract.Authority.AuthorityId));
            Assert.True(duplicate);
            await WaitUntilAsync(
                () => ReadOperationalLogTail(logStart)
                    .Split(
                        "event=runtime_unlock_retry_dispatch_authority_granted;",
                        StringSplitOptions.None)
                    .Length - 1 >= 2,
                TimeSpan.FromSeconds(2));
            var tail = ReadOperationalLogTail(logStart);
            Assert.Contains("settlement_outcome=MissingDispatch", tail, StringComparison.Ordinal);
            Assert.Contains("event=runtime_unlock_retry_missing_dispatch_successor_intent_created;", tail, StringComparison.Ordinal);
            Assert.Contains(
                "event=runtime_unlock_retry_dispatch_successor_evaluation_requested;",
                tail,
                StringComparison.Ordinal);
            Assert.Contains("event=runtime_unlock_retry_dispatch_stale_callback_ignored;", tail, StringComparison.Ordinal);
            Assert.Contains("decision_reason=callback_authority_not_captured", tail, StringComparison.Ordinal);
            Assert.Contains("decision_reason=runtime_unlock_payer_intent_send_rejected_before_retry_dispatch", tail, StringComparison.Ordinal);
            Assert.DoesNotContain("event=session_recovery_contract_failed;", tail, StringComparison.Ordinal);
            Assert.Equal(
                2,
                tail.Split("event=runtime_unlock_retry_dispatch_authority_granted;", StringSplitOptions.None).Length - 1);
        }
        finally
        {
            NknSignalingTransport.HelperPaidOfferHelpeePriorityDelayOverrideForTests = previousHelpeePriorityDelay;
            NknSignalingTransport.RuntimeUnlockRecoverySoftSettleDelayOverrideForTests = previousSoftSettleDelay;
            FakeNknClient.ResetNetwork();
        }
    }

