    [Fact]
    public void FileTransferReceiveRecovery_RejectsMissingOrMismatchedExecutionCommandWithoutStateCreation()
    {
        FakeNknClient.ResetNetwork();
        try
        {
            var options = NknTransportOptions.Load();
            var client = new FakeNknClient("regular.v4.composite.rejected.address");
            using var transport = new NknSignalingTransport(
                client,
                options,
                new NknIdentity("regular-v4-composite-rejected-id", client.Address),
                NknTunaAccelerationOptions.Disabled,
                accelerationLane: null);

            const string sessionId = "session_regular_v4_composite_rejected";
            const string transferId = "transfer_regular_v4_composite_rejected";
            var request = new FileTransferReceiveRecoveryRequest(
                sessionId,
                transferId,
                FileTransferDirection.Outbound,
                "session_liveness_timeout_pending")
            {
                RouteToken = FileTransferRouteResolver.RegularNknV4FastToken,
                ProtocolVersion = FileTransferProtocol.ProtocolVersionV4,
                LiveRouteEpoch = 1,
                TransferLegGeneration = 1,
                TransportEpoch = 1,
                BridgeRecoveryGeneration = 1,
                AuthorityReason = "session_liveness_timeout_pending",
                BridgeRecoveryAuthority = new FileTransferBridgeRecoveryAuthority(
                    sessionId,
                    transferId,
                    FileTransferDirection.Outbound,
                    FileTransferRouteResolver.RegularNknV4FastToken,
                    FileTransferProtocol.ProtocolVersionV4,
                    LiveRouteEpoch: 1,
                    RuntimeGeneration: 1,
                    TerminalGeneration: 0,
                    TransferLegGeneration: 1,
                    TransportEpoch: 1,
                    BridgeRecoveryGeneration: 1,
                    BridgeDecisionGeneration: 1,
                    RecoveryKind: "BridgeReceiveStallRecovery",
                    Reason: "session_liveness_timeout_pending"),
            };

            var missingStart = GetOperationalLogLength();
            Assert.Throws<InvalidOperationException>(
                () => transport.RequestFileTransferReceiveRecovery(request));
            var missingTail = ReadOperationalLogTail(missingStart);
            Assert.True(
                missingTail.Contains(
                    "rejection_reason=bridge_recovery_execution_command_missing",
                    StringComparison.Ordinal),
                missingTail);

            var validRequest = AttachBridgeRecoveryExecutionCommandForTests(request, leaseGeneration: 7);
            var command = Assert.IsType<FileTransferBridgeRecoveryExecutionCommand>(
                validRequest.BridgeRecoveryExecutionCommand);
            var mismatchedRequest = validRequest with
            {
                BridgeRecoveryExecutionCommand = command with
                {
                    Decision = command.Decision with
                    {
                        TransportEpoch = command.Decision.TransportEpoch + 1,
                    },
                },
            };
            var mismatchStart = GetOperationalLogLength();
            Assert.Throws<InvalidOperationException>(
                () => transport.RequestFileTransferReceiveRecovery(mismatchedRequest));
            var mismatchTail = ReadOperationalLogTail(mismatchStart);
            Assert.Contains(
                "rejection_reason=bridge_recovery_execution_command_scope_mismatch",
                mismatchTail,
                StringComparison.Ordinal);

            var unavailable = Assert.Throws<InvalidOperationException>(
                () => transport.RequestFileTransferReceiveRecovery(validRequest));
            Assert.Contains(
                "bridge_recovery_execution_bridge_unavailable",
                unavailable.Message,
                StringComparison.Ordinal);
        }
        finally
        {
            FakeNknClient.ResetNetwork();
        }
    }

    [Fact]
    [Trait("FileTransferInfraSuite", "ReceiveRecoveryOperation")]
    public void ReceiveRecoveryProof_ForwardsExactCommandWithoutInfraClosureState()
    {
        FakeNknClient.ResetNetwork();
        try
        {
            var options = NknTransportOptions.Load();
            var identity = new NknIdentity(
                "receive-recovery-proof-evidence-only-id",
                "receive.recovery.proof.evidence.only.address");
            using var adapter = new RealNknClientAdapter(identity, options);
            using var transport = new NknSignalingTransport(
                adapter,
                options,
                identity,
                NknTunaAccelerationOptions.Disabled,
                accelerationLane: null);
            var request = AttachBridgeRecoveryExecutionCommandForTests(
                new FileTransferReceiveRecoveryRequest(
                    "session_receive_recovery_proof_evidence",
                    "transfer_receive_recovery_proof_evidence",
                    FileTransferDirection.Inbound,
                    "session_liveness_timeout_pending")
                {
                    RouteToken =
                        FileTransferRouteResolver.RegularNknV4FastToken,
                    ProtocolVersion =
                        FileTransferProtocol.ProtocolVersionV4,
                    LiveRouteEpoch = 3,
                    TransferLegGeneration = 4,
                    TransportEpoch = 5,
                    BridgeRecoveryGeneration = 6,
                    AuthorityReason = "session_liveness_timeout_pending",
                },
                leaseGeneration: 9);
            var command =
                CreateBridgeRecoveryExecutionCommandForRegularV4AuthorityTest(
                    request);
            SetPrivateField(
                adapter,
                "lastFileTransferBridgeRecoveryExecutionReceipt",
                (FileTransferBridgeRecoveryExecutionReceipt?)
                    new FileTransferBridgeRecoveryExecutionReceipt(
                        command,
                        FileTransferBridgeRecoveryExecutionOutcome.Completed,
                        "hard",
                        "bridge_recovery_completed"));
            FileTransferReceiveRecoveryProofObservation? observed = null;
            var bridge =
                Assert.IsAssignableFrom<
                    IFileTransferBridgeRecoveryExecutionBridge>(transport);
            bridge.ReceiveRecoveryProofObserved += (_, args) =>
                observed = args.Observation;

            InvokePrivateMethod(
                transport,
                "ObserveFileTransferReceiveRecoveryProof",
                request.SessionId,
                request.TransferId,
                "file_transfer_data_frame",
                "control");

            var exact = Assert.IsType<FileTransferReceiveRecoveryProofObservation>(
                observed);
            Assert.Equal(command, exact.Command);
            Assert.Equal(
                $"file_transfer_data_frame:control:{command.Decision.BridgeDecisionGeneration}",
                exact.ProofIdentity);
            Assert.Null(
                typeof(NknSignalingTransport).GetField(
                    "fileTransferRegularV4RecoveryLivenessState",
                    BindingFlags.Instance |
                    BindingFlags.NonPublic));
            foreach (var legacyField in new[]
                     {
                         "fileTransferFallbackLegAuthorityState",
                         "pendingRuntimeUnlockRegularV4FrontierRepairSettlement",
                         "pendingRuntimeUnlockRegularV4RecoveryRetryJoinIntent",
                     })
            {
                Assert.Null(
                    typeof(NknSignalingTransport).GetField(
                        legacyField,
                        BindingFlags.Instance | BindingFlags.NonPublic));
            }

            foreach (var legacyMethod in new[]
                     {
                         "MarkFileTransferFallbackLegAuthorityStarted",
                         "MarkFileTransferFallbackLegAuthorityBridgeRecoveryLifecycle",
                         "MarkFileTransferRegularV4RecoveryLivenessStarted",
                         "MarkFileTransferRegularV4RecoveryLivenessReceiveProofReceived",
                         "HandleAcceptedRegularV4FrontierRepairSettlement",
                         "TryAdoptRuntimeUnlockRegularV4RecoveryLeaseClosure",
                         "TryConsumeRuntimeUnlockRegularV4RecoveryLeaseClosure",
                         "TryCaptureRuntimeUnlockRegularV4RecoveryRetryJoinIntent",
                         "ResolveFileTransferReceiveStallRecoveryBridgeReason",
                     })
            {
