                "runtime_unlock");
            var installedState =
                GetPrivateField(host, "runtimeUnlockRecoveryRetryState");
            Assert.NotNull(installedState);
            var contractState =
                GetPrivatePropertyValue<SessionRecoveryContractState>(
                    installedState,
                    "ContractState");
            var dispatchContract =
