    private static RuntimeUnlockRetryDispatchAuthorityRequest
        QueueExactFallbackPairedTailYieldRuntimeUnlockRetryForTests(
            NknSignalingTransport transport,
            string sessionId,
            string transferId,
            string retryReason,
            string recoveryReason)
    {
        InvokePrivateMethod(
            transport,
            "TrackAuthorizedFileTransferRouteHintForTests",
            transferId,
            FileTransferRouteResolver.PostTunaFallbackV6Token,
            FileTransferProtocol.ProtocolVersionV6,
            "fallback_paired_tail_yield",
            false,
            "fallback_tail_quiescent",
            "active",
            true,
            1L,
            null,
            1);
        var source = CaptureCurrentRuntimeUnlockFileTransferOwnerAuthorityForTests(
            transport,
            sessionId);
        var route = FileTransferRouteResolver.Resolve(FileTransferRoute.PostTunaFallbackV6);
        var owner = new RuntimeOwnerToken(
            sessionId,
            transferId,
            FileTransferDirection.Outbound,
            route.Route,
            route.TelemetryToken,
            route.ProtocolVersion,
            source.LiveRouteEpoch,
            source.RuntimeGeneration,
            source.TerminalGeneration,
            "post_tuna_fallback_v6",
            "fallback_paired_tail_yield");
        Assert.True(FileTransferRouteResolver.TryParseTelemetryToken(
            source.TargetRouteToken,
            out var targetRoute));
        var publication = new RoutePublicationToken(
            sessionId,
            transferId,
            FileTransferDirection.Outbound,
            owner,
            route.Route,
            route.TelemetryToken,
            route.ProtocolVersion,
            source.LiveRouteEpoch,
            source.RuntimeGeneration,
            source.TerminalGeneration,
            checked((int)source.LegGeneration),
            source.RouteCommitGeneration,
            targetRoute,
            source.TargetProtocolVersion,
            source.TargetTransport,
            source.RoutePublicationGeneration,
            FileTransferCoordinatorActionKind.RoutePublication,
            source.CoordinatorDecisionReason);
        var leg = new FileTransferLeg
        {
            LegId = "test-exact-fallback-paired-tail-yield",
            Generation = checked((int)source.LegGeneration),
            RouteSelection = route,
            ProtocolVersion = route.ProtocolVersion,
            LiveRouteEpochId = source.LiveRouteEpoch,
            TransportEpochId = 1,
            BridgeRecoveryGeneration = 1,
            StartedUtc = DateTimeOffset.UtcNow,
            State = FileTransferLegState.Active,
            CanSendData = true,
        };
        var liveRouteEpoch = new LiveRouteEpoch
        {
            EpochId = source.LiveRouteEpoch,
            RouteSelection = route,
            HandoffKind = FileTransferTransportHandoffKind.TunaToNormalFallback,
            TargetTransport = FileTransferTransportKind.RegularNkn,
            Reason = "fallback_paired_tail_yield",
            State = "started",
            RoutePublicationToken = publication,
        };
        var survival = new RuntimeUnlockFallbackSurvivalState(
            FallbackActive: true,
            FallbackCurrent: true,
            FallbackTerminalized: false,
            CheckpointDeliveryRecoveryPending: false,
            StateRefreshSendInFlight: false,
            DeferredStateRefreshPending: false,
            ProofReplayPending: false,
            ControlPlanePressurePending: false,
            BridgeRecoveryPending: false,
            FallbackTailRepairPending: false,
            PairedFallbackYieldGranted: true);
        var state = new FileTransferCoordinatorState(
            sessionId,
            transferId,
            FileTransferDirection.Outbound,
            false,
            route,
            liveRouteEpoch,
            leg,
            source.LiveRouteEpoch,
            leg.Generation,
            source.RuntimeGeneration,
            source.TerminalGeneration,
            owner,
            [leg],
            RuntimeUnlockFallbackSurvivalState: survival,
            CurrentRoutePublicationToken: publication,
            LastRoutePublicationGeneration: publication.PublicationGeneration,
            CurrentDataSessionIdentity: "test-data-session-1",
            CurrentDataSessionGeneration: 1);
        var yielded = FileTransferCoordinator.Apply(
            new FileTransferCoordinatorEvent(
                FileTransferCoordinatorEventKind.FallbackTailQuiescent,
                route,
                FileTransferTransportHandoffKind.TunaToNormalFallback,
                FileTransferTransportKind.RegularNkn,
                "fallback_tail_quiescent",
                FileTransferLegState.Active,
                CanSendData: true,
                CommittedChunkIndex: 0,
                HighestObservedChunkIndex: -1,
                TransportEpochId: leg.TransportEpochId,
                BridgeRecoveryGeneration: leg.BridgeRecoveryGeneration),
            state);
        Assert.Null(yielded.MutationRejectedReason);
        var tailYield = Assert.IsType<FallbackTailYieldDecision>(
            yielded.FallbackTailYieldDecision);
        state = yielded.State;
        var peerOwnerKey = FileTransferCoordinator.BuildFallbackTailYieldOwnerKey(
            sessionId,
            transferId,
            route.TelemetryToken,
            route.ProtocolVersion,
            tailYield.CurrentLiveRouteEpoch,
            leg.Generation,
            leg.BridgeRecoveryGeneration,
            leg.TransportEpochId,
            tailYield.CheckpointRequestIdSnapshot);
        var evidence = new FallbackPairedTailYieldReleaseEvidence(
            tailYield,
            new FileTransferAuthorityId(
                "fta2-fallback_tail_yield-0123456789abcdef01234567"),
            PeerPredecessorAuthorityId: null,
            PeerYieldGeneration: 1,
            FileTransferDirection.Inbound.ToString().ToLowerInvariant(),
            peerOwnerKey,
            tailYield.PairKey,
            tailYield.CurrentLiveRouteEpoch,
            leg.Generation,
            leg.BridgeRecoveryGeneration,
            leg.TransportEpochId,
            tailYield.CheckpointRequestIdSnapshot);
        var localReceipt =
            FileTransferCoordinator.CreateFallbackTailLocalProofReceipt(
                state,
                tailYield,
                "test-local-proof",
                "test-local-frame",
                observedUtcMs: 1);
        var localDecision =
            FileTransferCoordinator.ApplyFallbackTailLocalProofReceipt(
                state,
                localReceipt);
        Assert.True(localDecision.Accepted, localDecision.Reason);
        state = localDecision.State;
        Assert.True(
            Enum.TryParse<FileTransferDirection>(
                evidence.PeerDirection,
                ignoreCase: true,
                out var peerDirection));
        var peerProof = new FileTransferFallbackTailPeerProof(
            sessionId,
            transferId,
            peerDirection,
            evidence.PeerAuthorityId,
            evidence.PeerPredecessorAuthorityId,
            checked((int)evidence.PeerYieldGeneration),
            evidence.PeerOwnerKey,
            evidence.PeerPairKey,
            evidence.PeerLiveRouteEpoch,
            evidence.PeerLegGeneration,
            evidence.PeerBridgeRecoveryGeneration,
            evidence.PeerTransportEpoch,
            evidence.PeerCheckpointRequestIdSnapshot,
            CommittedChunkIndex: 0,
            HighestObservedChunkIndex: 0,
            FrameFingerprint: "test-peer-frame");
        var peerReceipt =
            FileTransferCoordinator.CreateFallbackTailPeerProofReceipt(
                state,
                peerProof,
                "test-peer-proof",
                observedUtcMs: 1);
        var peerDecision =
            FileTransferCoordinator.ApplyFallbackTailPeerProofReceipt(
                state,
                peerReceipt);
        Assert.True(peerDecision.Accepted, peerDecision.Reason);
        state = peerDecision.State;
        var pairedRelease =
            Assert.IsType<FileTransferFallbackTailPairedReleaseReceipt>(
                state.PersistentState.FallbackTailYield.CurrentOperation
                    ?.PairedRelease);
        Assert.True(
            FileTransferCoordinator
                .TryCreateFallbackPairedTailYieldRuntimeUnlockRetryDispatchRequest(
                    state,
                    pairedRelease,
                    retryReason,
                    recoveryReason,
                    out var request,
                    out var rejectionReason),
            rejectionReason);
        InstallRuntimeUnlockRetryDispatchCoordinatorForTests(
            transport,
            initialCoordinatorState: state);
        Assert.True(
            Assert.IsAssignableFrom<IRuntimeUnlockRetryDispatchAuthorityBridge>(transport)
                .QueueRuntimeUnlockRetryDispatchAuthorityRequest(request));
        return request;
    }

    private static RuntimeUnlockRetryDispatchSettlementReport
        SeedDispatchObservedPostTunaFallbackRuntimeUnlockRetryForTests(
            NknSignalingTransport transport,
            FileTransferRoutePublicationAuthority publication,
            long contractGeneration = 7,
            long retiredOfferGeneration = 11)
    {
        var request = new RuntimeUnlockRetryDispatchAuthorityRequest(
            publication.SessionId,
            publication.TransferId,
            publication.Direction,
            publication,
            contractGeneration,
            retiredOfferGeneration,
            DispatchAttemptGeneration: 1,
            RetryReason: "runtime_unlock_offer_send_not_observed",
            RecoveryReason: "post_tuna_fallback_previous_dispatch_observed",
            RegularV4LivenessGeneration: 0,
            BridgeDecisionGeneration: 0,
            PredecessorAuthorityId: null,
            RequestActivePredecessorSupersession: false,
            MissingDispatchSuccessorGeneration: 0);
        var contract = CreateFallbackTailRuntimeUnlockRetryDispatchContractForTests(request);
        var offerGeneration = checked(retiredOfferGeneration + 1);
        const string offerNonce = "test-previous-dispatch-observed";
        Assert.True(contract.TryBindOfferAlias(offerGeneration, offerNonce));
        Assert.True(contract.TryBeginSend(out var dispatchAttempt));
        Assert.True(contract.TryCreateObservedSettlementProposal(
            dispatchAttempt,
            "test_previous_dispatch_observed",
            out var report));
        Assert.True(contract.TryApplySettlementReport(report));

        var stateType = typeof(NknSignalingTransport).GetNestedType(
            "RuntimeUnlockRecoveryRetryState",
            BindingFlags.NonPublic);
        Assert.NotNull(stateType);
        var state = Activator.CreateInstance(stateType!, nonPublic: true);
        Assert.NotNull(state);

        void Set(string propertyName, object? value)
        {
            var property = stateType!.GetProperty(
                propertyName,
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            Assert.NotNull(property);
            property!.SetValue(state, value);
        }

        Set("ContractGeneration", contractGeneration);
        Set("RetiredOfferGeneration", retiredOfferGeneration);
        Set("SessionId", publication.SessionId);
        Set("TransferId", publication.TransferId);
        Set("RetryReason", request.RetryReason);
        Set("RecoveryReason", request.RecoveryReason);
        Set("CreatedUtcMs", DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
        Set("ContractState", SessionRecoveryContractState.RecoverySettled);
        Set("Settled", true);
        Set("DispatchAttemptGeneration", 1);
        Set("MissingDispatchSuccessorGeneration", 0);
        Set("SourcePublicationAuthority", publication);
        Set("PendingDispatchAuthorityRequest", request);
        Set("DispatchContract", contract);
        Set("LastAppliedDispatchSettlementReport", report);
        Set(
            "LastAppliedDispatchSettlementDecisionStatus",
            RuntimeUnlockRetryDispatchSettlementDecisionStatus.Accepted);
        Set("LastAppliedDispatchSettlementDecisionReason", "retry_dispatch_settlement_accepted");
        Set("DispatchDecisionStatus", RuntimeUnlockRetryDispatchDecisionStatus.Granted);
        Set("DispatchDecisionReason", "runtime_unlock_retry_dispatch_authorized");
        Set("DispatchAuthorityGranted", true);
        Set("DispatchObserved", true);

        SetPrivateField(transport, "runtimeUnlockRecoveryRetryState", state);
        return report;
    }

