    private new static object? InvokePrivateMethod(
        object target,
        string methodName,
        params object?[] args)
    {
        if (args.Length == 1 &&
            methodName is "MarkRuntimeUnlockRecoveryContractRetryDispatched")
        {
            var receipt =
                GetLastCommittedRuntimeUnlockRetryDispatchInstallReceipt(target);
            args = [args[0], receipt, receipt.HasValue];
        }
        else if (args.Length == 2 &&
                 methodName is
                     "MarkRuntimeUnlockRecoveryContractRetryDispatched")
        {
            args = [args[0], args[1], args[1] is not null];
        }
        else if (args.Length == 1 &&
            methodName is "ScheduleAccelerationNegotiationRetry" &&
            GetLastCommittedRuntimeUnlockRetryDispatchInstallReceipt(target) is
                { } receipt)
        {
            args = [args[0], receipt];
        }
        else if (args.Length == 2 &&
                 methodName is
                     "MarkRuntimeUnlockRecoveryContractListenerRearmCompleted" &&
                 GetLastCommittedRuntimeUnlockRetryDispatchInstallReceipt(target) is
                     { } listenerRearmReceipt)
        {
            args = [args[0], args[1], listenerRearmReceipt];
        }

        return CoreSmokeTestsBase.InvokePrivateMethod(target, methodName, args);
    }

    private static FileTransferReceiveRecoveryRequest AttachBridgeRecoveryExecutionCommandForTests(
        FileTransferReceiveRecoveryRequest request,
        int leaseGeneration = 1)
    {
        var routeToken = request.RouteToken ?? FileTransferRouteResolver.RegularNknV4FastToken;
        Assert.True(FileTransferRouteResolver.TryParseTelemetryToken(routeToken, out var route));
        var reason = string.IsNullOrWhiteSpace(request.Reason)
            ? "test_regular_v4_recovery"
            : request.Reason.Trim();
        var bridge = request.BridgeRecoveryAuthority is { } suppliedBridge
            ? suppliedBridge with
            {
                TransferLegGeneration = Math.Max(1, suppliedBridge.TransferLegGeneration),
                RecoveryKind = nameof(BridgeRecoveryKind.BridgeReceiveStallRecovery),
            }
            : new FileTransferBridgeRecoveryAuthority(
                request.SessionId,
                request.TransferId,
                request.Direction,
                routeToken,
                request.ProtocolVersion,
                request.LiveRouteEpoch,
                RuntimeGeneration: 1,
                TerminalGeneration: 0,
                Math.Max(1, request.TransferLegGeneration),
                request.TransportEpoch,
                request.BridgeRecoveryGeneration,
                BridgeDecisionGeneration: 1,
                RecoveryKind: nameof(BridgeRecoveryKind.BridgeReceiveStallRecovery),
                Reason: reason);
        var owner = new RuntimeOwnerToken(
            bridge.SessionId,
            bridge.TransferId,
            bridge.Direction,
            route,
            bridge.RouteToken,
            bridge.ProtocolVersion,
            bridge.LiveRouteEpoch,
            bridge.RuntimeGeneration,
            bridge.TerminalGeneration,
            "test_runtime",
            "test_coordinator_fixture");
        var lease = new RecoveryLivenessLease(
            bridge.SessionId,
            bridge.TransferId,
            bridge.Direction,
            owner,
            route,
            bridge.RouteToken,
            bridge.ProtocolVersion,
            bridge.LiveRouteEpoch,
            bridge.RuntimeGeneration,
            bridge.TerminalGeneration,
            bridge.TransferLegGeneration,
            bridge.TransportEpoch,
            bridge.BridgeRecoveryGeneration,
            Math.Max(1, leaseGeneration),
            new FileTransferAuthorityId(
                $"fta{FileTransferAuthoritySchema.Current}-test_regular_v4_recovery-{Math.Max(1, leaseGeneration):D8}"),
            RecoveryLivenessLeaseState.Active,
            bridge.Reason);
        var decision = new BridgeRecoveryDecision(
            Accepted: true,
            RecoveryKind: BridgeRecoveryKind.BridgeReceiveStallRecovery,
            Reason: bridge.Reason,
            BridgeDecisionGeneration: bridge.BridgeDecisionGeneration,
            CurrentRoute: route,
            CurrentProtocolVersion: bridge.ProtocolVersion,
            CurrentLiveRouteEpoch: bridge.LiveRouteEpoch,
            CurrentRuntimeGeneration: bridge.RuntimeGeneration,
            CurrentTerminalGeneration: bridge.TerminalGeneration,
            CurrentLegGeneration: bridge.TransferLegGeneration,
            TransportEpoch: bridge.TransportEpoch,
            BridgeRecoveryGeneration: bridge.BridgeRecoveryGeneration,
            RuntimeOwner: owner);
        return request with
        {
            RouteToken = bridge.RouteToken,
            ProtocolVersion = bridge.ProtocolVersion,
            LiveRouteEpoch = bridge.LiveRouteEpoch,
            TransferLegGeneration = bridge.TransferLegGeneration,
            TransportEpoch = bridge.TransportEpoch,
            BridgeRecoveryGeneration = bridge.BridgeRecoveryGeneration,
            BridgeRecoveryAuthority = bridge,
            BridgeRecoveryExecutionCommand =
                new FileTransferBridgeRecoveryExecutionCommand(
                    decision,
                    lease,
                    request.CheckpointRequestId),
        };
    }

