    private static void InstallRuntimeUnlockRetryDispatchCoordinatorForTests(
        NknSignalingTransport transport,
        Func<RuntimeUnlockRetryDispatchAuthorityRequest, RuntimeUnlockRetryDispatchDecisionStatus>? statusSelector = null,
        Func<RuntimeUnlockRetryDispatchDecision, RuntimeUnlockRetryDispatchDecision>? decisionTransform = null,
        bool installSettlementObserver = true,
        Func<RuntimeUnlockRetryDispatchSettlementDecision, RuntimeUnlockRetryDispatchSettlementDecision>?
            settlementDecisionTransform = null,
        Func<RuntimeUnlockRetryDispatchSettlementReport, bool>? terminalStateSelector = null,
        FileTransferCoordinatorState? initialCoordinatorState = null,
        bool installLifecycleEvaluationObservers = true,
        RuntimeUnlockRetryDispatchAuthorityRequest? initialCoordinatorRequest = null,
        Func<FileTransferCoordinatorState, FileTransferCoordinatorState>?
            initialCoordinatorStateTransform = null)
    {
        FileTransferCoordinatorState? coordinatorState = initialCoordinatorState;
        var bridge = Assert.IsAssignableFrom<IRuntimeUnlockRetryDispatchAuthorityBridge>(transport);

        void EnsureCoordinatorInstallState(
            RuntimeUnlockRetryDispatchAuthority expectedAuthority)
        {
            Assert.NotNull(coordinatorState);
            var receipt =
                GetLastCommittedRuntimeUnlockRetryDispatchInstallReceipt(transport);
            Assert.True(receipt.HasValue);
            Assert.Equal(expectedAuthority, receipt.Value.Authority);
            var retryState = GetPrivateField(
                transport,
                "runtimeUnlockRecoveryRetryState");
            Assert.NotNull(retryState);
            var coordinatorContract =
                Assert.IsType<RuntimeUnlockRetryDispatchContract>(
                    retryState!.GetType()
                        .GetProperty("DispatchContract")!
                        .GetValue(retryState));
            Assert.Equal(expectedAuthority, coordinatorContract.Authority);

            var lifecycle =
                FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(coordinatorState!);
            if (lifecycle.InstalledAttempt is { } installed &&
                installed.Authority == expectedAuthority)
            {
                return;
            }

            var exactDecision = new RuntimeUnlockRetryDispatchDecision(
                RuntimeUnlockRetryDispatchDecisionStatus.Granted,
                "accepted",
                coordinatorContract)
            {
                Request = receipt.Value.Request,
                State = coordinatorState!,
            };
            var stageResult = new RuntimeUnlockRetryDispatchDecisionStageResult(
                receipt.Value.StageStatus,
                "retry_dispatch_decision_staged",
                exactDecision)
            {
                StageDisposition = receipt.Value.StageDisposition,
                StageCleared = receipt.Value.StageCleared,
                StagedUtcMs = receipt.Value.StagedUtcMs,
                StageExpiresUtcMs = receipt.Value.StageExpiresUtcMs,
            };
            var stageDecision =
                FileTransferCoordinator.ObserveRuntimeUnlockRetryDispatchStage(
                    coordinatorState!,
                    stageResult,
                    receipt.Value.StagedUtcMs);
            Assert.True(stageDecision.Accepted, stageDecision.Reason);
            coordinatorState = stageDecision.State;

            var receiptDecision =
                FileTransferCoordinator.IssueRuntimeUnlockRetryDispatchInstallReceipt(
                    coordinatorState,
                    exactDecision,
                    receipt.Value.Request,
                    checked(
                        receipt.Value.DispatchDeadlineUtcMs -
                        Math.Max(
                            1L,
                            (long)(
                                FileTransferCoordinator
                                    .RuntimeUnlockRetryDispatchDeadlineOverrideForTests ??
                                TimeSpan.FromMilliseconds(
                                    FileTransferCoordinator
                                        .RuntimeUnlockRetryDispatchDeadlineMilliseconds))
                            .TotalMilliseconds)));
            Assert.True(receiptDecision.Accepted, receiptDecision.Reason);
            Assert.Equal(receipt.Value, receiptDecision.Receipt);
            coordinatorState = receiptDecision.State;

            var installDecision =
                FileTransferCoordinator.CommitRuntimeUnlockRetryDispatchInstall(
                    coordinatorState,
                    new RuntimeUnlockRetryDispatchInstallResult(
                        RuntimeUnlockRetryDispatchInstallStatus.Installed,
                        "retry_dispatch_install_committed",
                        receipt.Value),
                    checked(receipt.Value.StagedUtcMs + 1));
            Assert.True(installDecision.Accepted, installDecision.Reason);
            coordinatorState = installDecision.State;
        }

        bool ApplyCoordinatorInstallDecision(
            RuntimeUnlockRetryDispatchDecision decision)
        {
            Assert.NotNull(coordinatorState);
            var stageResult =
                bridge.StageRuntimeUnlockRetryDispatchDecision(decision);
            if (!stageResult.Accepted)
            {
                return false;
            }

            if (stageResult.StageDisposition ==
                RuntimeUnlockRetryDispatchStageDisposition.AlreadyInstalled)
            {
                return true;
            }

            var nowUtcMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            var stageDecision =
                FileTransferCoordinator.ObserveRuntimeUnlockRetryDispatchStage(
                    coordinatorState!,
                    stageResult,
                    nowUtcMs);
            if (!stageDecision.Accepted)
            {
                return false;
            }

            coordinatorState = stageDecision.State;
            var issuance =
                FileTransferCoordinator.IssueRuntimeUnlockRetryDispatchInstallReceipt(
                    coordinatorState,
                    decision,
                    decision.Request,
                    nowUtcMs);
            if (!issuance.Accepted ||
                issuance.Receipt is not { IsDefault: false } receipt)
            {
                return false;
            }

            coordinatorState = issuance.State;
            var installResult =
                bridge.CommitRuntimeUnlockRetryDispatchInstall(receipt);
            if (!installResult.Accepted)
            {
                return false;
            }

            var commitDecision =
                FileTransferCoordinator.CommitRuntimeUnlockRetryDispatchInstall(
                    coordinatorState,
                    installResult,
                    nowUtcMs);
            if (!commitDecision.Accepted)
            {
                return false;
            }

            coordinatorState = commitDecision.State;
            if (!bridge.ConfirmRuntimeUnlockRetryDispatchInstall(receipt))
            {
                return false;
            }

            if (commitDecision.PredecessorSettlementDecision is
                    { } predecessorSettlementDecision)
            {
                var observedDecision =
                    settlementDecisionTransform?.Invoke(
                        predecessorSettlementDecision) ??
                    predecessorSettlementDecision;
                if (!bridge.ObserveRuntimeUnlockRetryDispatchSettlementDecision(
                        observedDecision))
                {
                    return false;
                }
            }

            return true;
        }

        if (installLifecycleEvaluationObservers)
        {
            bridge.RuntimeUnlockRetryDispatchExecutionObserved += (_, args) =>
            {
                EnsureCoordinatorInstallState(args.Observation.Authority);
                Assert.True(
                    FileTransferCoordinator.TryGetCurrentRuntimeUnlockRetryDispatchInstallReceipt(
                        coordinatorState!,
                        out var installReceipt));
                Assert.Equal(installReceipt, args.Observation.InstallReceipt);
                var decision =
                    FileTransferCoordinator.ObserveRuntimeUnlockRetryDispatchExecutionState(
                        coordinatorState!,
                        args.Observation.InstallReceipt,
                        args.Observation.AttemptPhase,
                        args.Observation.OfferGeneration,
                        args.Observation.OfferNonce,
                        args.Observation.DispatchObserved);
                args.Decision = decision;
                if (decision.Accepted)
                {
                    coordinatorState = decision.State;
                }
                else
                {
                    Assert.Equal(
                        "retry_dispatch_execution_transition_invalid",
                        decision.Reason);
                }
            };

            bridge.RuntimeUnlockRetryDispatchDeadlineEvaluationRequested += (_, args) =>
            {
                EnsureCoordinatorInstallState(args.Evaluation.Authority);
                var decision =
                    FileTransferCoordinator.EvaluateRuntimeUnlockRetryDispatchDeadline(
                        coordinatorState!,
                        args.Evaluation.Authority.AuthorityId,
                        args.Evaluation.ObservedUtcMs);
                coordinatorState = decision.State;
                if (decision.Settlement is not { IsDefault: false } settlement)
                {
                    return;
                }

                var status = decision.Status switch
                {
                    RuntimeUnlockRetryLifecycleTransitionStatus.Accepted =>
                        RuntimeUnlockRetryDispatchSettlementDecisionStatus.Accepted,
                    RuntimeUnlockRetryLifecycleTransitionStatus.Idempotent =>
                        RuntimeUnlockRetryDispatchSettlementDecisionStatus.Idempotent,
                    _ => RuntimeUnlockRetryDispatchSettlementDecisionStatus.Rejected,
                };
                Assert.True(bridge.ObserveRuntimeUnlockRetryDispatchSettlementDecision(
                    new RuntimeUnlockRetryDispatchSettlementDecision(
                        status,
                        decision.Reason,
                        settlement)
                    {
                        State = decision.State,
                    }));
            };

            bridge.RuntimeUnlockRetryDispatchSuccessorEvaluationRequested += (_, args) =>
            {
                EnsureCoordinatorInstallState(args.Evaluation.PredecessorAuthority);
                var retryState = GetPrivateField(
                    transport,
                    "runtimeUnlockRecoveryRetryState");
                var localPredecessor =
                    Assert.IsType<RuntimeUnlockRetryDispatchContract>(
                        retryState!.GetType()
                            .GetProperty("DispatchContract")!
                            .GetValue(retryState));
                Assert.Equal(
                    args.Evaluation.PredecessorAuthority,
                    localPredecessor.Authority);
                var currentState = coordinatorState!;
                var successorDecision =
                     FileTransferCoordinator.PrepareRuntimeUnlockRetryDispatchSuccessor(
                         currentState,
                         args.Evaluation);
                if (successorDecision.Request is { } request &&
                    statusSelector?.Invoke(request) is { } selectedStatus &&
                    selectedStatus != RuntimeUnlockRetryDispatchDecisionStatus.Granted)
                {
                    successorDecision = new RuntimeUnlockRetryDispatchSuccessorDecision(
                        selectedStatus == RuntimeUnlockRetryDispatchDecisionStatus.Held
                            ? RuntimeUnlockRetryDispatchSuccessorDecisionStatus.Held
                            : RuntimeUnlockRetryDispatchSuccessorDecisionStatus.Rejected,
                        selectedStatus == RuntimeUnlockRetryDispatchDecisionStatus.Held
                             ? "test_coordinator_held"
                             : "test_coordinator_rejected",
                         args.Evaluation,
                         request)
                    {
                        State = currentState,
                    };
                }
                else
                {
                    coordinatorState = successorDecision.State;
                }

                _ = bridge.ObserveRuntimeUnlockRetryDispatchSuccessorDecision(
                    successorDecision);
                if (successorDecision.AuthorizationDecision is { } authorization)
                {
                    var appliedAuthorization =
                        decisionTransform?.Invoke(authorization) ?? authorization;
                    var installed =
                        ApplyCoordinatorInstallDecision(appliedAuthorization);
                    if (settlementDecisionTransform is null)
                    {
                        Assert.True(installed);
                    }
                }
            };
        }

        FileTransferCoordinatorState CreateCoordinatorState(
            RuntimeUnlockRetryDispatchAuthorityRequest request,
            bool prepareRetryRelease = true)
        {
            var publication = request.SourcePublicationAuthority;
            Assert.True(FileTransferRouteResolver.TryParseTelemetryToken(publication.RouteToken, out var route));
            Assert.True(FileTransferRouteResolver.TryParseTelemetryToken(publication.TargetRouteToken, out var targetRoute));
            var routeSelection = FileTransferRouteResolver.Resolve(route);
            var runtimeOwner = new RuntimeOwnerToken(
                request.SessionId,
                request.TransferId,
                request.Direction,
                route,
                publication.RouteToken,
                publication.ProtocolVersion,
                publication.LiveRouteEpoch,
                publication.RuntimeGeneration,
                publication.TerminalGeneration,
                "test_runtime",
                "test_coordinator_fixture");
            var sourcePublication = new RoutePublicationToken(
                request.SessionId,
                request.TransferId,
                request.Direction,
                runtimeOwner,
                route,
                publication.RouteToken,
                publication.ProtocolVersion,
                publication.LiveRouteEpoch,
                publication.RuntimeGeneration,
                publication.TerminalGeneration,
                checked((int)publication.LegGeneration),
                publication.RouteCommitGeneration,
                targetRoute,
                publication.TargetProtocolVersion,
                publication.TargetTransport,
                publication.RoutePublicationGeneration,
                FileTransferCoordinatorActionKind.RoutePublication,
                publication.CoordinatorDecisionReason);
            var fallbackPairedYieldEvidence =
                request.FallbackPairedTailYieldEvidence;
            var fallbackTailYield =
                fallbackPairedYieldEvidence?.LocalDecision;
            var leg = new FileTransferLeg
            {
                LegId = $"test-runtime-unlock-leg-{request.Direction.ToString().ToLowerInvariant()}",
                Generation = checked((int)publication.LegGeneration),
                RouteSelection = routeSelection,
                ProtocolVersion = publication.ProtocolVersion,
                LiveRouteEpochId = publication.LiveRouteEpoch,
                TransportEpochId =
                    fallbackPairedYieldEvidence?.PeerTransportEpoch ?? 0,
                BridgeRecoveryGeneration =
                    fallbackTailYield?.CurrentBridgeRecoveryGeneration ?? 0,
                CheckpointRequestId =
                    fallbackTailYield?.CheckpointRequestIdSnapshot,
                StartedUtc = DateTimeOffset.UtcNow,
                State = FileTransferLegState.Active,
                CanSendData = true,
            };
            var liveRouteEpoch = publication.LiveRouteEpoch > 0
                ? new LiveRouteEpoch
                {
                    EpochId = publication.LiveRouteEpoch,
                    RouteSelection = routeSelection,
                    HandoffKind = FileTransferTransportHandoffKind.None,
                    TargetTransport = publication.TargetTransport,
                    Reason = "test_coordinator_fixture",
                    State = "started",
                    RoutePublicationToken = sourcePublication,
                }
                : null;
            var preparesRecoveryLeaseClosure =
                route == FileTransferRoute.RegularNknV4Fast &&
                prepareRetryRelease &&
                (request.RegularV4LivenessGeneration > 0 || request.BridgeDecisionGeneration > 0);
            var releaseAuthorityId = new FileTransferAuthorityId(
                $"test-runtime-unlock-release-{request.RecoveryContractGeneration}");
            const int releaseGeneration = 1;
            RepairReplayDecision? repairDecision = null;
            var fallbackSurvival = RuntimeUnlockFallbackSurvivalState.Empty;
            FileTransferRegularV4FrontierRepairSettlement? repairSettlement = null;
            if (route == FileTransferRoute.RegularNknV4Fast &&
                prepareRetryRelease &&
                !preparesRecoveryLeaseClosure)
            {
                var repairAuthorityId = new FileTransferAuthorityId(
                    $"test-runtime-unlock-repair-{request.RecoveryContractGeneration}");
                repairDecision = new RepairReplayDecision(
                    Accepted: true,
                    RepairReplayKind.V4Repair,
                    "test_regular_v4_repair_settled",
                    releaseGeneration,
                    route,
                    publication.ProtocolVersion,
                    publication.LiveRouteEpoch,
                    publication.RuntimeGeneration,
                    publication.TerminalGeneration,
                    checked((int)publication.LegGeneration),
                    leg.TransportEpochId,
                    leg.BridgeRecoveryGeneration,
                    runtimeOwner,
                    repairAuthorityId,
                    PredecessorAuthorityId: null,
                    BridgeDecisionGeneration: 0,
                    sourcePublication);
                repairSettlement = new FileTransferRegularV4FrontierRepairSettlement(
                    request.SessionId,
                    request.TransferId,
                    request.Direction,
                    publication.RouteToken,
                    publication.ProtocolVersion,
                    publication.LiveRouteEpoch,
                    publication.RuntimeGeneration,
                    publication.TerminalGeneration,
                    publication.LegGeneration,
                    leg.TransportEpochId,
                    leg.BridgeRecoveryGeneration,
                    BridgeDecisionGeneration: 0,
                    sourcePublication.PublicationGeneration,
                    sourcePublication.RouteCommitGeneration,
                    RepairKey: "test_regular_v4_repair",
                    FrontierChunkIndex: 0,
                    DurableReceivedHighestChunkIndex: 0,
                    RequestedChunkCount: 1,
                    DecisionGeneration: releaseGeneration,
                    DecisionReason: "test_regular_v4_repair_settled",
                    FileTransferRegularV4FrontierRepairSettlementOutcome.MissingDispatch,
                    FileTransferTransportKind.RegularNkn)
                {
                    AuthorityId = repairAuthorityId,
                };
            }
            else if (route != FileTransferRoute.RegularNknV4Fast)
            {
                Assert.Equal(FileTransferRoute.PostTunaFallbackV6, route);
                fallbackSurvival =
                    fallbackTailYield?.FallbackSurvivalState ??
                    RuntimeUnlockFallbackSurvivalState.Empty;
            }

            var state = new FileTransferCoordinatorState(
                request.SessionId,
                request.TransferId,
                request.Direction,
                false,
                routeSelection,
                liveRouteEpoch,
                leg,
                publication.LiveRouteEpoch,
                leg.Generation,
                publication.RuntimeGeneration,
                publication.TerminalGeneration,
                runtimeOwner,
                [leg],
                RuntimeUnlockFallbackSurvivalState: fallbackSurvival,
                CurrentRoutePublicationToken: sourcePublication,
                LastRoutePublicationGeneration: sourcePublication.PublicationGeneration,
                CurrentRepairReplayDecision: repairDecision,
                LastRepairReplayGeneration: repairDecision?.RepairGeneration ?? 0,
                CurrentDataSessionIdentity: "test-data-session-1",
                CurrentDataSessionGeneration: 1);

            if (fallbackTailYield is { } exactTailYield &&
                fallbackPairedYieldEvidence is { } exactEvidence)
            {
                Assert.True(
                    Enum.TryParse<FileTransferDirection>(
                        exactEvidence.PeerDirection,
                        ignoreCase: true,
                        out var peerDirection));
                var scope = new FileTransferFallbackTailYieldScope(
                    request.SessionId,
                    request.TransferId,
                    request.Direction,
                    runtimeOwner,
                    sourcePublication,
                    route,
                    routeSelection.TelemetryToken,
                    publication.ProtocolVersion,
                    publication.LiveRouteEpoch,
                    publication.TerminalGeneration,
                    checked((int)publication.LegGeneration),
                    leg.TransportEpochId,
                    leg.BridgeRecoveryGeneration,
                    exactTailYield.CheckpointRequestIdSnapshot,
                    leg.CheckpointGeneration,
                    "test-data-session-1",
                    DataSessionGeneration: 1,
                    exactTailYield.OwnerKey,
                    exactTailYield.PairKey);
                var localReceipt =
                    new FileTransferFallbackTailLocalProofReceipt(
                        exactTailYield,
                        scope,
                        "test-local-proof",
                        "test-local-frame",
                        ObservedUtcMs: 1);
                var peerProof = new FileTransferFallbackTailPeerProof(
                    request.SessionId,
                    request.TransferId,
                    peerDirection,
                    exactEvidence.PeerAuthorityId,
                    exactEvidence.PeerPredecessorAuthorityId,
                    checked((int)exactEvidence.PeerYieldGeneration),
                    exactEvidence.PeerOwnerKey,
                    exactEvidence.PeerPairKey,
                    exactEvidence.PeerLiveRouteEpoch,
                    exactEvidence.PeerLegGeneration,
                    exactEvidence.PeerBridgeRecoveryGeneration,
                    exactEvidence.PeerTransportEpoch,
                    exactEvidence.PeerCheckpointRequestIdSnapshot,
                    CommittedChunkIndex: 0,
                    HighestObservedChunkIndex: 0,
                    FrameFingerprint: "test-peer-frame");
                var peerReceipt =
                    new FileTransferFallbackTailPeerProofReceipt(
                        peerProof,
                        scope,
                        "test-peer-proof",
                        ObservedUtcMs: 1);
                var pairedRelease =
                    new FileTransferFallbackTailPairedReleaseReceipt(
                        localReceipt,
                        peerReceipt,
                        PairingGeneration: 1,
                        RuntimeUnlockRetryReleaseKind
                            .FallbackPairedTailYield,
                        FallbackTailYieldKind.Quiescent.ToString());
                state = state with
                {
                    PersistentState = state.PersistentState with
                    {
                        FallbackTailYield =
                            new FileTransferFallbackTailYieldSubstate(
                                CurrentOperation:
                                    new FileTransferFallbackTailYieldOperation(
                                        exactTailYield,
                                        scope,
                                        FileTransferFallbackTailYieldPairingState
                                            .Paired,
                                        localReceipt,
                                        peerReceipt,
                                        pairedRelease),
                                LastYieldGeneration:
                                    exactTailYield.YieldGeneration,
                                LastPairingGeneration: 1),
                    },
                };
            }

            if (repairSettlement is { } exactRepairSettlement)
            {
                var settlementCommand =
                    new FileTransferRegularV4FrontierRepairPressureSettlementCommand(
                        exactRepairSettlement,
                        InstallGeneration: 1,
                        exactRepairSettlement.AuthorityId,
                        RetainedPredecessorAuthorityId: null);
                var settlementReceipt =
                    new FileTransferRegularV4FrontierRepairPressureSettlementApplyReceipt(
                        settlementCommand,
                        FileTransferRegularV4FrontierRepairPressureSettlementApplyStatus.Applied,
                        "applied",
                        CurrentAuthorityCleared: true,
                        RetainedPredecessorCleared: false);
                state = state with
                {
                    PersistentState = state.PersistentState with
                    {
                        RuntimeUnlockRetryLifecycle =
                            RuntimeUnlockRetryLifecycleSubstate.Empty with
                            {
                                RepairSettlementRelease =
                                    new RuntimeUnlockRetryLifecycleRepairSettlementRelease(
                                        exactRepairSettlement,
                                        settlementReceipt,
                                        RuntimeUnlockRetryLifecycleRepairSettlementReleaseState
                                            .Available),
                            },
                    },
                };
            }

            if (!preparesRecoveryLeaseClosure)
            {
                return state;
            }

            var bridgeDecisionGeneration = Math.Max(
                1,
                request.BridgeDecisionGeneration);
            var livenessGeneration = Math.Max(
                1,
                request.RegularV4LivenessGeneration);
            var observation = new FileTransferReceiveRecoveryObservation(
                request.SessionId,
                request.TransferId,
                request.Direction,
                route,
                publication.RouteToken,
                publication.ProtocolVersion,
                publication.LiveRouteEpoch,
                runtimeOwner,
                sourcePublication,
                RouteCommit: null,
                publication.TerminalGeneration,
                checked((int)publication.LegGeneration),
                leg.TransportEpochId,
                leg.BridgeRecoveryGeneration,
                leg.CheckpointRequestId,
                "test-data-session-1",
                DataSessionGeneration: 1,
                Source: "test",
                Reason: "test_receive_recovery_started",
                ObservationIdentity:
                    $"test-receive-recovery-{request.RecoveryContractGeneration}",
                ObservationGeneration: 1,
                ObservedUtcMs: 1);
            var bridgeDecision = new BridgeRecoveryDecision(
                Accepted: true,
                BridgeRecoveryKind.BridgeReceiveStallRecovery,
                observation.Reason,
                bridgeDecisionGeneration,
                route,
                publication.ProtocolVersion,
                publication.LiveRouteEpoch,
                publication.RuntimeGeneration,
                publication.TerminalGeneration,
                checked((int)publication.LegGeneration),
                leg.TransportEpochId,
                leg.BridgeRecoveryGeneration,
                runtimeOwner);
            var activeLease = new RecoveryLivenessLease(
                request.SessionId,
                request.TransferId,
                request.Direction,
                runtimeOwner,
                route,
                publication.RouteToken,
                publication.ProtocolVersion,
                publication.LiveRouteEpoch,
                publication.RuntimeGeneration,
                publication.TerminalGeneration,
                checked((int)publication.LegGeneration),
                leg.TransportEpochId,
                leg.BridgeRecoveryGeneration,
                livenessGeneration,
                new FileTransferAuthorityId(
                    $"test-runtime-unlock-release-{request.RecoveryContractGeneration}-{livenessGeneration}"),
                RecoveryLivenessLeaseState.Active,
                observation.Reason);
            var executionCommand =
                new FileTransferBridgeRecoveryExecutionCommand(
                    bridgeDecision,
                    activeLease,
                    leg.CheckpointRequestId);
            var operationAuthority =
                new FileTransferReceiveRecoveryOperationAuthority(
                    observation,
                    bridgeDecision,
                    new FileTransferBridgeRecoveryAuthority(
                        request.SessionId,
                        request.TransferId,
                        request.Direction,
                        publication.RouteToken,
                        publication.ProtocolVersion,
                        publication.LiveRouteEpoch,
                        publication.RuntimeGeneration,
                        publication.TerminalGeneration,
                        checked((int)publication.LegGeneration),
                        leg.TransportEpochId,
                        leg.BridgeRecoveryGeneration,
                        bridgeDecisionGeneration,
                        nameof(BridgeRecoveryKind.BridgeReceiveStallRecovery),
                        observation.Reason),
                    activeLease,
                    executionCommand,
                    OperationGeneration: 1,
                    new FileTransferAuthorityId(
                        $"test-receive-recovery-operation-{request.RecoveryContractGeneration}"));
            var completionReceipt =
                new FileTransferBridgeRecoveryExecutionReceipt(
                    executionCommand,
                    FileTransferBridgeRecoveryExecutionOutcome.Completed,
                    "soft_then_hard",
                    "test_receive_recovery_completed");
            var retiredLease = activeLease with
            {
                State = RecoveryLivenessLeaseState.Retired,
                Reason = completionReceipt.Reason,
            };
            var operation = new FileTransferReceiveRecoveryOperation(
                operationAuthority,
                FileTransferReceiveRecoveryExecutionState.Completed,
                FileTransferBridgeRecoveryExecutionStartStatus.Started,
                "bridge_recovery_execution_started",
                new FileTransferBridgeRecoveryExecutionStartResult(
                    executionCommand,
                    FileTransferBridgeRecoveryExecutionStartStatus.Started,
                    "bridge_recovery_execution_started",
                    Task.FromResult(completionReceipt)),
                completionReceipt,
                new FileTransferReceiveRecoveryProof(
                    operationAuthority,
                    "test_receive_recovery_proof",
                    "receive_proof_observed",
                    ObservedUtcMs: 2),
                retiredLease,
                FileTransferReceiveRecoveryClosureState.Adopted,
                ClosureGeneration: 1);
            return state with
            {
                PersistentState = state.PersistentState with
                {
                    FileTransferReceiveRecovery =
                        new FileTransferReceiveRecoverySubstate(
                            CurrentOperation: operation,
                            LastTerminalOperation: null,
                            LastOperationGeneration: 1,
                            LastClosureGeneration: 1),
                },
            };
        }

        if (coordinatorState is null &&
            initialCoordinatorRequest is { IsDefault: false } bootstrapRequest)
        {
            coordinatorState = CreateCoordinatorState(bootstrapRequest);
            coordinatorState =
                initialCoordinatorStateTransform?.Invoke(coordinatorState) ??
                coordinatorState;
        }

        if (installSettlementObserver)
        {
            bridge.RuntimeUnlockRetryDispatchSettlementReported += (_, args) =>
            {
                var currentReceipt =
                    GetLastCommittedRuntimeUnlockRetryDispatchInstallReceipt(
                        transport);
                if (currentReceipt?.Authority == args.Report.Authority)
                {
                    EnsureCoordinatorInstallState(args.Report.Authority);
                }
                if (terminalStateSelector?.Invoke(args.Report) == true)
                {
                    var retryLifecycle = coordinatorState!.PersistentState
                        .RuntimeUnlockRetryLifecycle;
                    coordinatorState = coordinatorState! with
                    {
                        IsTerminal = true,
                        PersistentState = coordinatorState.PersistentState with
                        {
                            RuntimeUnlockRetryLifecycle = retryLifecycle with
                            {
                                PendingAttempt = null,
                                InstalledAttempt = null,
                            },
                        },
                    };
                }
                var settlementDecision = FileTransferCoordinator.ObserveRuntimeUnlockRetryDispatchSettlement(
                    coordinatorState!,
                    args.Report);
                coordinatorState = settlementDecision.State;

                var observedDecision = settlementDecisionTransform?.Invoke(settlementDecision) ??
                    settlementDecision;
                var observed = bridge.ObserveRuntimeUnlockRetryDispatchSettlementDecision(observedDecision);
                if (settlementDecisionTransform is null)
                {
                    Assert.True(observed);
                }
            };

        }
        RuntimeUnlockRetryDispatchDecision DecideRequest(
            RuntimeUnlockRetryDispatchAuthorityRequest request)
        {
            coordinatorState ??= CreateCoordinatorState(request);
            var selectedStatus = statusSelector?.Invoke(request) ??
                RuntimeUnlockRetryDispatchDecisionStatus.Granted;
            if (selectedStatus != RuntimeUnlockRetryDispatchDecisionStatus.Granted)
            {
                return new RuntimeUnlockRetryDispatchDecision(
                    selectedStatus,
                    selectedStatus == RuntimeUnlockRetryDispatchDecisionStatus.Held
                        ? "test_coordinator_held"
                        : "test_coordinator_rejected",
                    null)
                {
                    Request = request,
                    State = coordinatorState,
                };
            }

            RuntimeUnlockRetryReleaseKind releaseKind;
            FileTransferAuthorityId? releaseAuthorityId;
            int releaseGeneration;
            string releaseOutcome;
            if (coordinatorState.RouteSelection.Route == FileTransferRoute.RegularNknV4Fast)
            {
                if ((request.RegularV4LivenessGeneration > 0 ||
                     request.BridgeDecisionGeneration > 0) &&
                    FileTransferCoordinator.GetReceiveRecoverySubstate(
                            coordinatorState)
                        .CurrentOperation is
                    {
                        ClosureState:
                            FileTransferReceiveRecoveryClosureState.Adopted,
                        RetiredRecoveryLivenessLease: { } closureLease,
                    })
                {
                    releaseKind = RuntimeUnlockRetryReleaseKind.ReceiveRecoveryLeaseClosure;
                    releaseAuthorityId = closureLease.AuthorityId;
                    releaseGeneration = closureLease.LeaseGeneration;
                    releaseOutcome = RecoveryLivenessLeaseState.Retired.ToString();
                }
                else if (FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(
                             coordinatorState).RepairSettlementRelease is
                    {
                        State:
                            RuntimeUnlockRetryLifecycleRepairSettlementReleaseState.Available,
                    } release)
                {
                    releaseKind = RuntimeUnlockRetryReleaseKind.RegularV4RepairSettlement;
                    releaseAuthorityId = release.Settlement.AuthorityId;
                    releaseGeneration = release.Settlement.DecisionGeneration;
                    releaseOutcome = release.Settlement.Outcome.ToString();
                }
                else
                {
                    releaseKind = RuntimeUnlockRetryReleaseKind.Unknown;
                    releaseAuthorityId = null;
                    releaseGeneration = 0;
                    releaseOutcome = string.Empty;
                }
            }
            else
            {
                var tailYield = Assert.IsType<FallbackTailYieldDecision>(
                    coordinatorState.PersistentState.FallbackTailYield
                        .CurrentOperation?.Decision);
                releaseKind = RuntimeUnlockRetryReleaseKind.FallbackPairedTailYield;
                releaseAuthorityId = tailYield.AuthorityId;
                releaseGeneration = tailYield.YieldGeneration;
                releaseOutcome = tailYield.YieldKind.ToString();
            }

            var decision = FileTransferCoordinator.AuthorizeRuntimeUnlockRetryDispatch(
                coordinatorState,
                request,
                releaseKind,
                releaseAuthorityId,
                releaseGeneration,
                releaseOutcome);
            coordinatorState = decision.State;

            return decisionTransform?.Invoke(decision) ?? decision;
        }

        transport.RuntimeUnlockRetryDispatchAuthorityDecisionOverrideForTests =
            DecideRequest;
        transport.RuntimeUnlockRetryDispatchInitialEvaluationDecisionOverrideForTests =
            evaluation =>
            {
                var bootstrapRequest =
                    new RuntimeUnlockRetryDispatchAuthorityRequest(
                        evaluation.SessionId,
                        evaluation.TransferId,
                        evaluation.Direction,
                        evaluation.SourcePublicationAuthority,
                        evaluation.RecoveryContractGeneration,
                        evaluation.RetiredOfferGeneration,
                        DispatchAttemptGeneration: 1,
                        evaluation.RetryReason,
                        evaluation.RecoveryReason,
                        evaluation.RegularV4LivenessGeneration,
                        evaluation.BridgeDecisionGeneration,
                        PredecessorAuthorityId: null,
                        RequestActivePredecessorSupersession: false,
                        MissingDispatchSuccessorGeneration: 0)
                    {
                        FallbackPairedTailYieldEvidence =
                            evaluation.FallbackPairedTailYieldEvidence,
                        ListenerRearmRequirement =
                            evaluation.ListenerRearmRequirement,
                    };
                coordinatorState ??= CreateCoordinatorState(bootstrapRequest);
                Assert.True(
                    FileTransferCoordinator
                        .TryPrepareRuntimeUnlockRetryDispatchInitialRequest(
                            coordinatorState,
                            evaluation,
                            out var request,
                            out var reason),
                    reason);
                return DecideRequest(request);
            };
    }

    private static async Task<RuntimeUnlockRetryDispatchInstallFixture>
        CreateRuntimeUnlockRetryDispatchInstallFixtureAsync(
            string testName,
            bool installLifecycleEvaluationObservers = false,
            bool requiresLocalListenerRetry = false)
    {
        FakeNknClient.ResetNetwork();
        var suffix = $"{testName}-{Guid.NewGuid():N}";
        var options = NknTransportOptions.Load();
        var hostClient = new FakeNknClient($"host.{suffix}.address");
        var helperClient = new FakeNknClient($"helper.{suffix}.address");
        var host = new NknSignalingTransport(
            hostClient,
            options,
            new NknIdentity($"host-{suffix}-id", hostClient.Address),
            NknTunaAccelerationOptions.Disabled,
            accelerationLane: null);
        var helper = new NknSignalingTransport(
            helperClient,
            options,
            new NknIdentity($"helper-{suffix}-id", helperClient.Address));
        try
        {
            using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(8));
            var sessionId = await ApproveNknSessionAsync(
                host,
                helper,
                cts.Token,
                InviteCapabilities.Chat | InviteCapabilities.FileTransfer);
            var transferId = $"transfer_{suffix}";
            var decisions = new List<RuntimeUnlockRetryDispatchDecision>();
            InstallRuntimeUnlockRetryDispatchCaptureCoordinatorForTests(
                host,
                decisions,
                installLifecycleEvaluationObservers);
            _ = await host.OpenFileTransferDataSessionAsync(sessionId, transferId, cts.Token);
            TrackAuthorizedRegularV4RouteForTests(host, transferId);
            InvokePrivateMethod(
                host,
                "ArmRuntimeUnlockRetryAfterRecovery",
                0L,
                sessionId,
                "runtime_unlock_offer_send_not_observed",
                "regular_v4_repair_settled",
                requiresLocalListenerRetry);

            Assert.Single(decisions);
            var state = GetPrivateField(host, "runtimeUnlockRecoveryRetryState");
            Assert.NotNull(state);
            return new RuntimeUnlockRetryDispatchInstallFixture(
                host,
                helper,
                Assert.IsAssignableFrom<IRuntimeUnlockRetryDispatchAuthorityBridge>(host),
                state!,
                decisions,
                sessionId,
                transferId);
        }
        catch
        {
            host.Dispose();
            helper.Dispose();
            FakeNknClient.ResetNetwork();
            throw;
        }
    }

    private static RuntimeUnlockRetryDispatchInstallReceipt
        CreateRuntimeUnlockRetryDispatchInstallReceipt(
            RuntimeUnlockRetryDispatchDecision decision,
            RuntimeUnlockRetryDispatchDecisionStageResult stage,
            long installGeneration,
            RuntimeUnlockRetryDispatchAuthority? authority = null)
    {
        var contract = Assert.IsType<RuntimeUnlockRetryDispatchContract>(decision.Contract);
        var deadline = FileTransferCoordinator.RuntimeUnlockRetryDispatchDeadlineOverrideForTests ??
            TimeSpan.FromMilliseconds(
                FileTransferCoordinator.RuntimeUnlockRetryDispatchDeadlineMilliseconds);
        var deadlineMilliseconds = Math.Max(
            1L,
            (long)deadline.TotalMilliseconds);
        return new RuntimeUnlockRetryDispatchInstallReceipt(
            authority ?? contract.Authority,
            installGeneration)
        {
            Request = decision.Request,
            StageStatus = stage.Status,
            StageDisposition = stage.StageDisposition,
            StageCleared = stage.StageCleared,
            StagedUtcMs = stage.StagedUtcMs,
            StageExpiresUtcMs = stage.StageExpiresUtcMs,
            DispatchDeadlineUtcMs = checked(
                stage.StagedUtcMs + 1 + deadlineMilliseconds),
        };
    }

    private static (
        FileTransferCoordinatorState State,
        RuntimeUnlockRetryDispatchInstallReceipt Receipt)
        IssueRuntimeUnlockRetryDispatchInstallReceiptForTests(
            RuntimeUnlockRetryDispatchDecision decision,
            RuntimeUnlockRetryDispatchDecisionStageResult stage)
    {
        var stageDecision =
            FileTransferCoordinator.ObserveRuntimeUnlockRetryDispatchStage(
                decision.State,
                stage,
                stage.StagedUtcMs);
        Assert.True(stageDecision.Accepted, stageDecision.Reason);
        var observedUtcMs = checked(stage.StagedUtcMs + 1);
        var issuance =
            FileTransferCoordinator.IssueRuntimeUnlockRetryDispatchInstallReceipt(
                stageDecision.State,
                decision,
                decision.Request,
                observedUtcMs);
        Assert.True(issuance.Accepted, issuance.Reason);
        var receipt = Assert.IsType<RuntimeUnlockRetryDispatchInstallReceipt>(
            issuance.Receipt);
        return (issuance.State, receipt);
    }

    private static (
        FileTransferCoordinatorState State,
        RuntimeUnlockRetryDispatchInstallReceipt Receipt,
        RuntimeUnlockRetryDispatchInstallResult InstallResult,
        RuntimeUnlockRetryLifecycleTransitionDecision CommitDecision)
        InstallRuntimeUnlockRetryDispatchThroughCoordinatorForTests(
            RuntimeUnlockRetryDispatchInstallFixture fixture,
            RuntimeUnlockRetryDispatchDecision decision,
            RuntimeUnlockRetryDispatchDecisionStageResult stage)
    {
        var issued =
            IssueRuntimeUnlockRetryDispatchInstallReceiptForTests(
                decision,
                stage);
        var installResult =
            fixture.Bridge.CommitRuntimeUnlockRetryDispatchInstall(
                issued.Receipt);
        Assert.True(installResult.Accepted, installResult.Reason);
        var commitDecision =
            FileTransferCoordinator.CommitRuntimeUnlockRetryDispatchInstall(
                issued.State,
                installResult,
                checked(issued.Receipt.StagedUtcMs + 1));
        Assert.True(commitDecision.Accepted, commitDecision.Reason);
        Assert.True(
            fixture.Bridge.ConfirmRuntimeUnlockRetryDispatchInstall(
                issued.Receipt));
        if (commitDecision.PredecessorSettlementDecision is
            { } predecessorSettlementDecision)
        {
            var settlementLogStart = GetOperationalLogLength();
            var predecessorSettlementApplied =
                fixture.Bridge.ObserveRuntimeUnlockRetryDispatchSettlementDecision(
                    predecessorSettlementDecision);
            Assert.True(
                predecessorSettlementApplied,
                ReadOperationalLogTail(settlementLogStart));
        }

        fixture.CoordinatorState = commitDecision.State;
        return (
            commitDecision.State,
            issued.Receipt,
            installResult,
            commitDecision);
    }

    private static void InstallRuntimeUnlockRetryDispatchExecutionObserverForTests(
        RuntimeUnlockRetryDispatchInstallFixture fixture)
    {
        fixture.Bridge.RuntimeUnlockRetryDispatchExecutionObserved += (_, args) =>
        {
            var decision =
                FileTransferCoordinator.ObserveRuntimeUnlockRetryDispatchExecutionState(
                    fixture.CoordinatorState,
                    args.Observation.InstallReceipt,
                    args.Observation.AttemptPhase,
                    args.Observation.OfferGeneration,
                    args.Observation.OfferNonce,
                    args.Observation.DispatchObserved);
            args.Decision = decision;
            if (decision.Accepted)
            {
                fixture.CoordinatorState = decision.State;
            }
        };
    }

    private static RuntimeUnlockRetryDispatchDecision
        CreateCoordinatorActiveSuccessorDecisionForTests(
            RuntimeUnlockRetryDispatchInstallFixture fixture,
            long retiredOfferGeneration = 1)
    {
        var transport = fixture.Host;
        var bridge =
            Assert.IsAssignableFrom<IRuntimeUnlockRetryDispatchAuthorityBridge>(
                transport);
        var predecessorLifecycle =
            FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(
                fixture.CoordinatorState);
        var predecessor = Assert.IsType<RuntimeUnlockRetryDispatchContract>(
            GetPrivateField(
                fixture.Host,
                "runtimeUnlockRecoveryRetryState")!
                .GetType()
                .GetProperty("DispatchContract")!
                .GetValue(
                    GetPrivateField(
                        fixture.Host,
                        "runtimeUnlockRecoveryRetryState")));
        Assert.Equal(
            predecessor.Authority,
            predecessorLifecycle.InstalledAttempt?.Authority);
        Assert.True(
            transport.BindRuntimeUnlockRetryDispatchOfferAliasForTests(
                retiredOfferGeneration,
                "test-active-predecessor-offer"));
        Assert.True(
            FileTransferCoordinator.TryGetCurrentRuntimeUnlockRetryDispatchInstallReceipt(
                fixture.CoordinatorState,
                out var installReceipt));
        var executionDecision =
            FileTransferCoordinator.ObserveRuntimeUnlockRetryDispatchExecutionState(
                fixture.CoordinatorState,
                installReceipt,
                RuntimeUnlockRetryDispatchAttemptPhase.AliasBound,
                retiredOfferGeneration,
                "test-active-predecessor-offer",
                dispatchObserved: false);
        Assert.True(executionDecision.Accepted, executionDecision.Reason);
        fixture.CoordinatorState = executionDecision.State;
        var successor =
             FileTransferCoordinator.PrepareRuntimeUnlockRetryDispatchSuccessor(
                 executionDecision.State,
                 predecessor.Authority,
                 retiredOfferGeneration);
        Assert.Equal(
            RuntimeUnlockRetryDispatchSuccessorDecisionStatus.Requested,
            successor.Status);
        fixture.CoordinatorState = successor.State;
        Assert.True(bridge.ObserveRuntimeUnlockRetryDispatchSuccessorDecision(successor));
        Assert.True(successor.AuthorizationDecision.HasValue);
        return successor.AuthorizationDecision.Value;
    }

    private static bool BindRuntimeUnlockRetryDispatchOfferAliasAndObserveForTests(
        NknSignalingTransport transport,
        long offerGeneration,
        string offerNonce)
    {
        if (!transport.BindRuntimeUnlockRetryDispatchOfferAliasForTests(
                offerGeneration,
                offerNonce))
        {
            return false;
        }

        var state = GetPrivateField(
            transport,
            "runtimeUnlockRecoveryRetryState");
        var contract = Assert.IsType<RuntimeUnlockRetryDispatchContract>(
            state!.GetType().GetProperty("DispatchContract")!.GetValue(state));
        var installReceipt =
            GetCurrentRuntimeUnlockRetryDispatchInstallReceiptForTests(transport);
        InvokePrivateMethod(
            transport,
            "PublishRuntimeUnlockRetryDispatchExecutionObservation",
            new RuntimeUnlockRetryDispatchExecutionObservation(
                contract.Authority,
                RuntimeUnlockRetryDispatchAttemptPhase.AliasBound,
                offerGeneration,
                offerNonce,
                DispatchObserved: false)
            {
                InstallReceipt = installReceipt,
            });
        return true;
    }

    private static bool BeginRuntimeUnlockRetryDispatchSendAndObserveForTests(
        NknSignalingTransport transport)
    {
        var state = GetPrivateField(
            transport,
            "runtimeUnlockRecoveryRetryState");
        var contract = Assert.IsType<RuntimeUnlockRetryDispatchContract>(
            state!.GetType().GetProperty("DispatchContract")!.GetValue(state));
        var installReceipt =
            GetCurrentRuntimeUnlockRetryDispatchInstallReceiptForTests(transport);
        if (!transport.BeginRuntimeUnlockRetryDispatchSendForTests())
        {
            return false;
        }

        InvokePrivateMethod(
            transport,
            "PublishRuntimeUnlockRetryDispatchExecutionObservation",
            new RuntimeUnlockRetryDispatchExecutionObservation(
                contract.Authority,
                RuntimeUnlockRetryDispatchAttemptPhase.SendInFlight,
                contract.OfferGeneration,
                contract.OfferNonce,
                DispatchObserved: false)
            {
                InstallReceipt = installReceipt,
            });
        return true;
    }

    private static bool SettleRuntimeUnlockRetryDispatchMissingForBoundOfferForTests(
        NknSignalingTransport transport,
        string sessionId,
        long offerGeneration,
        string reason)
    {
        if (!BeginRuntimeUnlockRetryDispatchSendAndObserveForTests(transport))
        {
            return false;
        }

        return Assert.IsType<bool>(InvokePrivateMethod(
            transport,
            "TrySettleRuntimeUnlockRetryDispatchMissingIfCurrent",
            sessionId,
            offerGeneration,
            reason));
    }

    private static RuntimeUnlockRetryDispatchInstallReceipt
        GetCurrentRuntimeUnlockRetryDispatchInstallReceiptForTests(
